SELECT COALESCE(SUM(s.output), 0)
FROM mine_development_data md
         JOIN sub_mine_development_data s
              ON s.mine_development_dataID = md.id
WHERE md.unit_name = #{unitName}
  AND md.record_date = #{recordDate}
  AND md.data_type = #{dataType}

SELECT COALESCE(SUM(s.output), 0)
FROM mine_development_data md
         JOIN sub_mine_development_data s
              ON s.mine_development_dataID = md.id
WHERE md.unit_name = #{unitName}
  AND md.record_date BETWEEN #{fromDate} AND #{toDate}
  AND md.data_type = #{dataType}

SELECT COALESCE(SUM(sub.day_plan), 0)
FROM mine_plan mp
         JOIN sub_mine_plan sub
              ON sub.mine_plan_id = mp.id
WHERE mp.plan_type = #{planType}
  AND mp.plan_month = #{planMonth}
  AND mp.unit_name  = #{unitName}
  AND mp.is_deleted = 0
  and sub.unit_name='计划总量'
